<h1><?=e($p['name'])?></h1><form class="form-stack" method="post" action="<?=e(url('admin/action.php'))?>"><?=csrf_input()?><input type="hidden" name="operation" value="product"><input type="hidden" name="id" value="<?=$id?>"><div class="form-grid"><label class="field">Nom<input name="name" value="<?=e($p['name'])?>" maxlength="120" required></label><label class="field">Prix en TND (vide : non commercialisable)<input name="price" inputmode="decimal" value="<?=$p['price_millimes']===null?'':e(number_format((int)$p['price_millimes']/1000,3,'.',''))?>"></label><label class="field">Catégorie<select name="category_id"><?php foreach(db()->query('SELECT * FROM categories ORDER BY sort_order') as $cat):?><option value="<?=$cat['id']?>" <?=$cat['id']===$p['category_id']?'selected':''?>><?=e($cat['name'])?></option><?php endforeach;?></select></label><label class="field">Coloris de référence<select name="default_color_id"><?php foreach(all_colors() as $color):?><option value="<?=$color['id']?>" <?=$color['id']===$p['default_color_id']?'selected':''?>><?=e($color['name'])?></option><?php endforeach;?></select></label></div><label class="field">Phrase courte<input name="short_description" value="<?=e($p['short_description'])?>" maxlength="400" required></label><label class="field">Description<textarea name="description" rows="4" maxlength="8000" required><?=e($p['description'])?></textarea></label><label class="field">Matière & composition exacte<textarea name="composition" rows="3" maxlength="4000"><?=e($p['composition'])?></textarea></label><label class="field">Entretien<textarea name="care" rows="2" maxlength="4000"><?=e($p['care'])?></textarea></label><label class="field">Guide des tailles / mesures en cm<textarea name="size_guide" rows="4" maxlength="4000"><?=e($p['size_guide'])?></textarea></label><label class="check-label"><input type="checkbox" name="active" value="1" <?=$p['active']?'checked':''?>> Publier cette pièce</label><h2>Stock réel par variante</h2><p>0 : indisponible. Les couleurs ou tailles sans stock sont exclues des filtres de disponibilité.</p><div class="stock-grid"><?php foreach($variants as $v):?><label class="field"><?=e($v['color_name'].' / '.$v['size_label'])?><input type="number" min="0" max="9999" required name="stock[<?=$v['id']?>]" value="<?=$v['stock']?>"><input type="hidden" name="version[<?=$v['id']?>]" value="<?=$v['revision']?>"></label><?php endforeach;?></div><button class="button">Enregistrer la pièce & le stock</button></form>
