<?php elseif($section==='orders'):$state=is_string($_GET['status']??null)?$_GET['status']:'';$valid=['pending','confirmed','packed','shipped','delivered','cancelled'];$offset=max(0,min(100000,(int)($_GET['offset']??0)));$sql='SELECT * FROM orders';$params=[];if(in_array($state,$valid,true)){$sql.=' WHERE status=?';$params[]=$state;}$sql.=' ORDER BY id DESC LIMIT 30 OFFSET '.$offset;$s=db()->prepare($sql);$s->execute($params);$orders=$s->fetchAll();?><h1>Commandes.</h1><form method="get"><input type="hidden" name="section" value="orders"><label class="field">État<select name="status"><option value="">Tous</option><?php foreach($valid as $v):?><option <?=$state===$v?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></label><button class="button-outline">Filtrer</button></form><div class="table-wrap"><table class="data-table"><thead><tr><th>Commande</th><th>Cliente</th><th>Total</th><th>État</th><th>Date</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><a href="<?=e(admin_url('order',['id'=>$o['id']]))?>"><?=e($o['reference'])?></a></td><td><?=e($o['customer_name'])?></td><td><?=e(money((int)$o['total_millimes']))?></td><td><?=e($o['status'])?></td><td><?=e($o['created_at'])?></td></tr><?php endforeach;?></tbody></table></div><nav class="pagination"><?php if($offset):?><a href="<?=e(admin_url('orders',['offset'=>max(0,$offset-30),'status'=>$state]))?>">← Précédentes</a><?php endif;if(count($orders)===30):?><a href="<?=e(admin_url('orders',['offset'=>$offset+30,'status'=>$state]))?>">Suivantes →</a><?php endif;?></nav>
<?php elseif($section==='order'):$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM orders WHERE id=?');$s->execute([$id]);$o=$s->fetch();if(!$o):echo '<h1>Commande introuvable.</h1>';else:$s=db()->prepare('SELECT * FROM order_items WHERE order_id=?');$s->execute([$id]);$items=$s->fetchAll();?><p class="eyebrow">COMMANDE</p><h1><?=e($o['reference'])?></h1><div class="form-grid"><div><h2>Livraison</h2><p><?=e($o['customer_name'])?><br><?=e($o['phone'])?><br><?=e($o['email'])?></p><p><?=nl2br(e($o['address']))?><br><?=e($o['postal_code'].' '.$o['governorate'])?></p><p><?=nl2br(e($o['notes']))?></p></div><div class="cart-summary"><h2>Récapitulatif</h2><?php foreach($items as $it):?><div class="summary-row"><span><?=e($it['product_name'])?> ×<?=$it['quantity']?><small><?=e($it['color_name'].' / '.$it['size_label'])?></small></span><strong><?=e(money((int)$it['unit_price_millimes']*$it['quantity']))?></strong></div><?php endforeach;?><p>Livraison : <?=e(money((int)$o['shipping_millimes']))?></p><p>Total : <?=e(money((int)$o['total_millimes']))?></p></div></div><form method="post" action="<?=e(url('admin/action.php'))?>" data-confirm="Confirmer le changement d’état ?"><?=csrf_input()?><input type="hidden" name="operation" value="order_status"><input type="hidden" name="id" value="<?=$id?>"><label class="field">État<select name="status"><?php foreach(['pending','confirmed','packed','shipped','delivered','cancelled'] as $v):?><option <?=$o['status']===$v?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></label><button class="button">Mettre à jour</button></form><h2>Historique</h2><?php $s=db()->prepare('SELECT status,created_at FROM order_history WHERE order_id=? ORDER BY id');$s->execute([$id]);foreach($s as $h):?><p><?=e($h['created_at'].' — '.$h['status'])?></p><?php endforeach;endif;?>
<?php elseif($section==='messages'):$offset=max(0,(int)($_GET['offset']??0));$messages=db()->query('SELECT * FROM messages ORDER BY id DESC LIMIT 30 OFFSET '.$offset)->fetchAll();?><h1>Messages.</h1><?php foreach($messages as $m):?><article class="message-card"><h2><?=e($m['name'])?></h2><p><?=e($m['email'].' · '.$m['created_at'])?></p><p><?=nl2br(e($m['message']))?></p><?php if(!$m['is_read']):?><form method="post" action="<?=e(url('admin/action.php'))?>"><?=csrf_input()?><input type="hidden" name="operation" value="message_read"><button class="button-outline" name="id" value="<?=$m['id']?>">Marquer comme lu</button></form><?php endif;?></article><?php endforeach;if(count($messages)===30):?><a href="<?=e(admin_url('messages',['offset'=>$offset+30]))?>">Messages suivants →</a><?php endif;?>
<?php elseif($section==='users'):$users=db()->query('SELECT id,name,email,role,active,created_at FROM users ORDER BY id DESC LIMIT 100')->fetchAll();?><h1>Comptes.</h1><div class="table-wrap"><table class="data-table"><thead><tr><th>Nom</th><th>E-mail</th><th>Rôle</th><th>État</th><th></th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td><td><?=$u['active']?'Actif':'Suspendu'?></td><td><?php if($u['role']==='customer'):?><form method="post" action="<?=e(url('admin/action.php'))?>"><?=csrf_input()?><input type="hidden" name="operation" value="user_toggle"><button class="text-button" name="id" value="<?=$u['id']?>"><?=$u['active']?'Suspendre':'Réactiver'?></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div></main><?php require ROOT.'/includes/footer.php';?>
